/*!
 * Perrito peludo 3D - widget para una esquina de la página
 * -------------------------------------------------------
 * Un perrito sentado que saluda con la patita y mueve los ojos (sigue el cursor,
 * mira alrededor y parpadea). El modelo 3D va incrustado en este archivo
 * (16.869 vértices, 33.742 triángulos, cuantizado a 16 bits), sin archivos externos.
 *
 * Uso (requiere three.js r128 cargado antes):
 *   <script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
 *   <script src="perrito-widget.js"></script>
 *
 * Opciones (opcional):
 *   Perrito.create({ corner: 'bottom-right' | 'bottom-left', size: 300, zIndex: 50 })
 *   Para controlarlo tú, define window.PERRITO_MANUAL = true antes de cargar el script.
 */
(function (global) {
  'use strict';

  // ---------------------------------------------------------------- datos del modelo
  const DATA = {"min":[-0.8193,0.0,-1.5815],"max":[0.8193,2.2,1.5815],"pos":"","idx":"","col":"","w":"","pivot":[0.136,0.51,0.714],"eyes":[[-0.33,1.78,1.27],[0.1,1.76,1.37]],"eyeR":0.085};

  // ---------------------------------------------------------------- ajustes de animación
  const YAW = -0.45;          // hacia dónde mira el perrito (rad), hacia el centro de la página
  const WAVE_AMP = 0.34;      // amplitud del saludo (rad)
  const WAVE_SPEED = 9;       // velocidad del saludo
  const WAVE_CYCLE = 6.5;     // segundos entre saludos
  const WAVE_LEN = 3.4;       // duración de cada saludo (s)

  const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
  const smooth = (a, b, x) => { const t = clamp((x - a) / (b - a), 0, 1); return t * t * (3 - 2 * t); };
  const rand = (a, b) => a + Math.random() * (b - a);

  function decode(b64, Type) {
    const s = atob(b64), u = new Uint8Array(s.length);
    for (let i = 0; i < s.length; i++) u[i] = s.charCodeAt(i);
    return new Type(u.buffer);
  }

  // ---------------------------------------------------------------- geometría
  function buildGeometry(d) {
    const q = decode(d.pos, Uint16Array), pos = new Float32Array(q.length);
    for (let i = 0; i < q.length; i++) {
      const a = i % 3;
      pos[i] = d.min[a] + (q[i] / 65535) * (d.max[a] - d.min[a]);
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    g.setAttribute('color', new THREE.BufferAttribute(decode(d.col, Uint8Array), 3, true));
    g.setAttribute('aW', new THREE.BufferAttribute(decode(d.w, Uint8Array), 1, true)); // peso del brazo
    g.setIndex(new THREE.BufferAttribute(decode(d.idx, Uint16Array), 1));
    g.computeVertexNormals();
    return g;
  }

  // Material con "hueso" de brazo: rota los vértices con peso alrededor de un pivote (en la GPU)
  function buildMaterial(pivot, uAng) {
    const m = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.88, metalness: 0 });
    m.onBeforeCompile = (s) => {
      s.uniforms.uAng = uAng;
      s.uniforms.uPiv = { value: new THREE.Vector3(...pivot) };
      s.vertexShader = s.vertexShader
        .replace('#include <common>', `#include <common>
          attribute float aW; uniform float uAng; uniform vec3 uPiv;
          mat3 rotY(float a){ float c=cos(a), s=sin(a); return mat3(c,0.,-s, 0.,1.,0., s,0.,c); }`)
        .replace('#include <beginnormal_vertex>', `#include <beginnormal_vertex>
          objectNormal = rotY(uAng*aW) * objectNormal;`)
        .replace('#include <begin_vertex>', `#include <begin_vertex>
          transformed = uPiv + rotY(uAng*aW) * (transformed - uPiv);`);
    };
    return m;
  }

  // ---------------------------------------------------------------- ojos
  function irisTexture() {
    const c = document.createElement('canvas'); c.width = 512; c.height = 256;
    const g = c.getContext('2d');
    g.fillStyle = '#140c08'; g.fillRect(0, 0, 512, 256);
    const cx = 128, cy = 128;                       // u = 0.25 -> dirección +Z de la esfera
    const gr = g.createRadialGradient(cx, cy, 8, cx, cy, 72);
    gr.addColorStop(0, '#1c0e08'); gr.addColorStop(0.5, '#6a3416'); gr.addColorStop(1, '#2b150a');
    g.fillStyle = gr; g.beginPath(); g.arc(cx, cy, 72, 0, Math.PI * 2); g.fill();
    g.fillStyle = '#050302'; g.beginPath(); g.arc(cx, cy, 34, 0, Math.PI * 2); g.fill();
    return new THREE.CanvasTexture(c);
  }

  function buildEye(pos, R, tex) {
    const root = new THREE.Group(); root.position.set(...pos);
    const ball = new THREE.Mesh(
      new THREE.SphereGeometry(R, 32, 24),
      new THREE.MeshStandardMaterial({ map: tex, roughness: 0.12, metalness: 0 }));
    root.add(ball);
    const white = new THREE.MeshBasicMaterial({ color: 0xffffff });   // brillos fijos (no giran con la mirada)
    const g1 = new THREE.Mesh(new THREE.SphereGeometry(R * 0.2, 12, 8), white);
    g1.position.set(-R * 0.33, R * 0.38, R * 0.86); root.add(g1);
    const g2 = new THREE.Mesh(new THREE.SphereGeometry(R * 0.1, 10, 8), white);
    g2.position.set(R * 0.3, -R * 0.26, R * 0.92); root.add(g2);
    return { root, ball };
  }

  // ---------------------------------------------------------------- widget
  function create(opts) {
    if (!global.THREE) throw new Error('Perrito: carga three.js antes de este script');
    opts = Object.assign({ corner: 'bottom-right', size: 300, zIndex: 50 }, opts);
    const mirror = /left/.test(opts.corner);
    const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;

    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
    const cv = renderer.domElement;
    Object.assign(cv.style, {
      position: 'fixed', bottom: 'env(safe-area-inset-bottom,0px)', [mirror ? 'left' : 'right']: 0,
      width: `min(${opts.size}px, 52vw)`, height: `min(${opts.size}px, 52vw)`,
      pointerEvents: 'none', zIndex: opts.zIndex, transform: mirror ? 'scaleX(-1)' : ''
    });
    cv.setAttribute('aria-hidden', 'true');
    document.body.appendChild(cv);

    const scene = new THREE.Scene();
    const cam = new THREE.PerspectiveCamera(28, 1, 0.1, 50);
    cam.position.set(0, 1.7, 6.6); cam.lookAt(0, 1.05, 0);
    scene.add(new THREE.HemisphereLight(0xfff2e0, 0x5a4a3a, 1.0));
    const key = new THREE.DirectionalLight(0xffffff, 1.1); key.position.set(2, 4, 5); scene.add(key);
    const rim = new THREE.DirectionalLight(0xffd6a8, 0.5); rim.position.set(-4, 2, -3); scene.add(rim);

    const uAng = { value: 0 };
    const dog = new THREE.Group(); scene.add(dog);
    dog.add(new THREE.Mesh(buildGeometry(DATA), buildMaterial(DATA.pivot, uAng)));

    const tex = irisTexture(), eyes = DATA.eyes.map((p) => buildEye(p, DATA.eyeR, tex));
    eyes.forEach((e) => dog.add(e.root));

    // sombra suave en el suelo
    const sc = document.createElement('canvas'); sc.width = sc.height = 128;
    const sx = sc.getContext('2d'), sg = sx.createRadialGradient(64, 64, 0, 64, 64, 64);
    sg.addColorStop(0, 'rgba(0,0,0,.35)'); sg.addColorStop(1, 'rgba(0,0,0,0)');
    sx.fillStyle = sg; sx.fillRect(0, 0, 128, 128);
    const shadow = new THREE.Mesh(new THREE.PlaneGeometry(4.2, 4.2),
      new THREE.MeshBasicMaterial({ map: new THREE.CanvasTexture(sc), transparent: true, depthWrite: false }));
    shadow.rotation.x = -Math.PI / 2; shadow.position.y = 0.01; scene.add(shadow);

    // --- estado de la mirada
    const gaze = { x: 0, y: 0 }, target = { x: -0.3, y: 0 };
    let lastPointer = -1e9, nextWander = 0, nextBlink = 2000, blinkStart = -1;
    const onMove = (e) => {
      const r = cv.getBoundingClientRect();
      const nx = clamp((e.clientX - (r.left + r.width / 2)) / (innerWidth * 0.5), -1, 1) * (mirror ? -1 : 1);
      const ny = clamp((e.clientY - (r.top + r.height * 0.35)) / (innerHeight * 0.5), -1, 1);
      target.x = clamp(nx * 1.0 - YAW, -0.55, 0.55);
      target.y = clamp(ny * 0.5, -0.35, 0.4);
      lastPointer = performance.now();
    };
    addEventListener('pointermove', onMove, { passive: true });

    function resize() {
      const w = cv.clientWidth, h = cv.clientHeight;
      renderer.setSize(w, h, false); cam.aspect = w / h; cam.updateProjectionMatrix();
    }
    addEventListener('resize', resize); resize();

    let raf = 0;
    function frame(now) {
      raf = requestAnimationFrame(frame);
      const t = now / 1000;

      // saludo con la patita
      const ph = t % WAVE_CYCLE;
      const env = reduce ? 0 : smooth(0, 0.35, ph) * (1 - smooth(WAVE_LEN - 0.5, WAVE_LEN, ph));
      uAng.value = env * Math.sin(t * WAVE_SPEED) * WAVE_AMP;

      // respiración y balanceo suave
      dog.scale.y = 1 + (reduce ? 0 : Math.sin(t * 2.1) * 0.006);
      dog.rotation.y = YAW + (reduce ? 0 : Math.sin(t * 0.7) * 0.03);

      // la mirada: sigue el cursor; si no hay movimiento, mira alrededor
      if (!reduce && now - lastPointer > 3000 && now > nextWander) {
        target.x = rand(-0.5, 0.35); target.y = rand(-0.2, 0.3);
        nextWander = now + rand(1200, 3000);
      }
      gaze.x += (target.x - gaze.x) * 0.14; gaze.y += (target.y - gaze.y) * 0.14;

      // parpadeo
      if (blinkStart < 0 && now > nextBlink) blinkStart = now;
      let lid = 1;
      if (blinkStart >= 0) {
        const k = (now - blinkStart) / 160;
        lid = k >= 1 ? 1 : 1 - Math.sin(k * Math.PI) * 0.92;
        if (k >= 1) { blinkStart = -1; nextBlink = now + rand(2500, 6000); }
      }
      eyes.forEach((e) => { e.ball.rotation.set(gaze.y, gaze.x, 0); e.root.scale.y = lid; });

      renderer.render(scene, cam);
    }
    raf = requestAnimationFrame(frame);

    return {
      destroy() {
        cancelAnimationFrame(raf);
        removeEventListener('pointermove', onMove); removeEventListener('resize', resize);
        cv.remove(); renderer.dispose();
      }
    };
  }

  global.Perrito = { create };
  if (!global.PERRITO_MANUAL) {
    const start = () => create();
    document.readyState === 'loading' ? addEventListener('DOMContentLoaded', start) : start();
  }
})(window);
